from typing import List

def isCircle(N: int, A: List[str]) -> int:
    # Check if the first character of the first string matches the last character of the last string
    if A[0][0] != A[-1][-1]:
        return 0

    # Check if each string can be chained with the next one
    for i in range(N - 1):
        if A[i][-1] != A[i + 1][0]:
            return 0

